          ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.fillStyle = 'rgba(255,58,122,' + (0.12 + 0.08 * Math.sin(f / 6 + tx)) + ')'; ctx.fillRect(X, Y - 20, 16, 20); ctx.restore();
